using System.Text.Json;
using XboxHresultBot.Entries;

namespace XboxHresultBot.Database;

public sealed class TitleIdDatabase
{
    private readonly string _path;
    private readonly List<TitleIdEntry> _entries = new();

    public TitleIdDatabase(string path)
    {
        _path = path;
        Load();
    }

    public IReadOnlyList<TitleIdEntry> All => _entries;

    public TitleIdEntry? Find(string input)
    {
        string query = Normalize(input);

        return _entries.FirstOrDefault(x =>
            Normalize(x.TitleId) == query ||
            Normalize(x.ShortName) == query ||
            Normalize(x.Game) == query);
    }

    public List<TitleIdEntry> Search(string query)
    {
        query = query.Trim();

        return _entries
            .Where(x =>
                x.Game.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                x.ShortName.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                x.TitleId.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                x.Publisher.Contains(query, StringComparison.OrdinalIgnoreCase) ||
                x.Notes.Contains(query, StringComparison.OrdinalIgnoreCase))
            .OrderBy(x => x.Game)
            .Take(25)
            .ToList();
    }

    private void Load()
    {
        if (!File.Exists(_path))
        {
            _entries.AddRange(DefaultEntries());
            Save();
            return;
        }

        string json = File.ReadAllText(_path);
        var loaded = JsonSerializer.Deserialize<List<TitleIdEntry>>(json);

        if (loaded != null)
            _entries.AddRange(loaded);
    }

    private void Save()
    {
        File.WriteAllText(_path, JsonSerializer.Serialize(_entries, new JsonSerializerOptions
        {
            WriteIndented = true
        }));
    }

    private static string Normalize(string value)
    {
        return value
            .Trim()
            .Replace("0x", "", StringComparison.OrdinalIgnoreCase)
            .Replace(" ", "")
            .Replace("-", "")
            .Replace("_", "")
            .ToUpperInvariant();
    }

